    requestId: message.requestId,
    section: message.section,
    catalogVersion: directory.catalogVersion,
    scope: message.section === "monster" ? "account" : "character",
    revision: samePage ? last.revision + 1 : 1,
    page: message.page,
    serverNowMs: 1
